import { z } from "zod";
import { json, mutation, readJson, requireUser } from "@/lib/http";
import { payroll } from "@/lib/payroll";

const schema = z.object({
  amountZec: z.string().trim().regex(/^\d{1,8}(\.\d{1,8})?$/, "Enter a ZEC amount like 0.25 (max 8 decimals)."),
  // Generated by the client per claim form; repeats return the original claim.
  idempotencyKey: z.string().regex(/^[A-Za-z0-9_-]{8,128}$/, "Invalid request key."),
});

type Ctx = { params: Promise<{ streamId: string }> };

export const POST = mutation(async (req, { params }: Ctx) => {
  const user = await requireUser(req);
  const { streamId } = await params;
  const b = await readJson(req, schema);
  const out = await payroll.reserveClaim(user.id, streamId, b.amountZec, b.idempotencyKey);
  return json(out, out.duplicate ? 200 : 201);
});
